INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3800, 'know', '/noʊ/', 'verb', '{"zh-TW":["知道；認識"],"en":["to be aware of","to be familiar with"]}', NULL, 'know-how / as far as I know', '[{"en":"We have the technical know-how.","zh-TW":"我們有技術專業知識。"},{"en":"As far as I know, the deal is still on.","zh-TW":"據我所知，交易還在進行中。"}]', '{"verb":"know","noun":"knowledge","adjective":"known","noun2":"know-how"}', NULL, 1, 3800, NULL),
(3801, 'know-how', '/ˈnoʊˌhaʊ/', 'noun', '{"zh-TW":["專業技術；實際知識"],"en":["practical knowledge and expertise in a field"]}', NULL, 'technical know-how / transfer know-how / accumulate know-how', '[{"en":"The company''s competitive advantage lies in its manufacturing know-how.","zh-TW":"公司的競爭優勢在於其製造專業技術。"},{"en":"Staff training helps transfer know-how across generations of employees.","zh-TW":"員工培訓有助於在各代員工之間傳遞專業知識。"}]', NULL, NULL, 3, 3801, NULL),
(3802, 'knowledge', '/ˈnɑːlɪdʒ/', 'noun', '{"zh-TW":["知識；了解"],"en":["facts, information, and skills acquired through experience or education"]}', NULL, 'to my knowledge / common knowledge / knowledge of', '[{"en":"A good knowledge of English is essential for this job.","zh-TW":"良好的英語知識對這份工作至關重要。"},{"en":"To my knowledge, no one has complained.","zh-TW":"據我所知，沒有人抱怨。"}]', '{"noun":"knowledge","adjective":"knowledgeable"}', NULL, 3, 3802, NULL),
(3803, 'knowledge base', '/ˈnɒlɪdʒ beɪs/', 'noun', '{"zh-TW":["知識庫"],"en":["a repository of information about a product or organization"]}', NULL, 'build a knowledge base / access the knowledge base', '[{"en":"The IT department maintains a knowledge base for common issues.","zh-TW":"IT部門為常見問題維護了知識庫。"},{"en":"Employees can find answers in the company knowledge base.","zh-TW":"員工可以在公司知識庫中找到答案。"}]', NULL, NULL, 5, 3803, NULL),
(3804, 'knowledge management', '/ˈnɒlɪdʒ ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["知識管理"],"en":["organizing and sharing an organization''s intellectual assets effectively"]}', NULL, 'knowledge management system / implement knowledge management', '[{"en":"A knowledge management system reduces time spent searching for information.","zh-TW":"知識管理系統減少了搜索信息所花費的時間。"},{"en":"Knowledge management is critical when key staff leave the company.","zh-TW":"當關鍵員工離開公司時，知識管理至關重要。"}]', '{"noun":"knowledge manager"}', NULL, 5, 3804, NULL),
(3805, 'knowledge transfer', '/ˈnɒlɪdʒ ˈtrænsfer/', 'noun', '{"zh-TW":["知識轉移"],"en":["the sharing of knowledge, skills, or experience between individuals or organizations"]}', NULL, 'facilitate knowledge transfer / knowledge transfer program / effective knowledge transfer', '[{"en":"Knowledge transfer programs ensure expertise is passed on to new staff.","zh-TW":"知識轉移計畫確保專業知識傳遞給新員工。"},{"en":"Technology licensing facilitates knowledge transfer between firms.","zh-TW":"技術許可促進了公司之間的知識轉移。"}]', NULL, NULL, 5, 3805, NULL),
(3806, 'kosher', '/ˈkəʊʃər/', 'adjective', '{"zh-TW":["符合猶太飲食規定的"],"en":["conforming to Jewish dietary laws"]}', NULL, 'kosher meal / kosher certified', '[{"en":"Kosher meals are available on request for the flight.","zh-TW":"航班上可根據要求提供符合猶太教規的餐食。"},{"en":"The hotel has a kosher-certified kitchen.","zh-TW":"飯店設有符合猶太教規認證的廚房。"}]', NULL, NULL, 2, 3806, NULL),
(3807, 'KPI', '/ˌkeɪ piː ˈaɪ/', 'noun', '{"zh-TW":["關鍵績效指標"],"en":["key performance indicator; a measurable value showing how effectively goals are met"]}', NULL, 'set KPIs / meet KPIs / KPI dashboard / track KPIs', '[{"en":"Each team member has individual KPIs aligned to company goals.","zh-TW":"每位團隊成員都有與公司目標一致的個人關鍵績效指標。"},{"en":"The KPI showed a 20% improvement in customer satisfaction.","zh-TW":"關鍵績效指標顯示客戶滿意度提升了20%。"}]', '{"full form":"key performance indicator"}', NULL, 1, 3807, NULL),
(3808, 'KPI dashboard', '/ˌkeɪ piː ˈaɪ ˈdæʃbɔːrd/', 'noun', '{"zh-TW":["關鍵績效指標儀表板"],"en":["a visual display showing key performance metrics in real time"]}', NULL, 'build a KPI dashboard / monitor the KPI dashboard / KPI dashboard report', '[{"en":"The KPI dashboard gives executives a real-time view of performance.","zh-TW":"關鍵績效指標儀表板為高管提供績效的即時視圖。"},{"en":"All departments share a common KPI dashboard.","zh-TW":"所有部門共用一個共同的KPI儀表板。"}]', NULL, NULL, 5, 3808, NULL),
(3809, 'KYC', '/keɪ waɪ siː/', 'noun', '{"zh-TW":["了解您的客戶；客戶身份驗證"],"en":["Know Your Customer procedures to verify client identity"]}', NULL, 'complete KYC / KYC requirements', '[{"en":"Banks must complete KYC procedures for new account holders.","zh-TW":"銀行必須對新帳戶持有人完成客戶身份驗證程序。"},{"en":"KYC requirements prevent financial fraud and money laundering.","zh-TW":"客戶身份驗證要求防止金融詐騙和洗錢。"}]', NULL, NULL, 1, 3809, NULL),
(3810, 'lab test', '/læb tɛst/', 'noun', '{"zh-TW":["實驗室檢查；化驗"],"en":["a medical test performed in a laboratory"]}', NULL, 'order a lab test / lab test results', '[{"en":"The doctor ordered several lab tests to confirm the diagnosis.","zh-TW":"醫生要求進行幾項化驗以確認診斷。"},{"en":"Lab test results are usually available within 24 hours.","zh-TW":"化驗結果通常在24小時內可查看。"}]', NULL, NULL, 3, 3810, NULL),
(3811, 'label', '/ˈleɪbl/', 'noun', '{"zh-TW":["標籤","貼標籤；稱呼"],"en":["a piece of paper attached to an object giving information about it","a piece of paper giving information about something","to attach a label to; to categorize"]}', '{"root":{"text":"label","meaning":"strip/ribbon (帶子)"},"logic":"源自古法語，指貼在物品上的資訊帶。"}', 'price label / brand label; product label / label as', '[{"en":"Check the label for washing instructions.","zh-TW":"查看標籤上的洗滌說明。"},{"en":"The label shows the country of origin.","zh-TW":"標籤顯示原產地。"},{"en":"Check the label for the ingredients list.","zh-TW":"查看標籤上的成分表。"},{"en":"The product was labeled as organic.","zh-TW":"該產品被標註為有機產品。"}]', '{"verb":"label","noun":"label"}', NULL, 2, 3811, NULL),
(3812, 'labor', '/ˈleɪbər/', 'noun', '{"zh-TW":["勞動；勞工"],"en":["physical or mental work; workers as a group"]}', NULL, 'labor market / labor force / labor costs', '[{"en":"The company is trying to reduce labor costs.","zh-TW":"公司正在努力降低勞動成本。"},{"en":"There is a shortage in the labor market.","zh-TW":"勞動市場存在短缺。"}]', '{"noun":"labor, laborer","verb":"labor","adjective":"laborious"}', NULL, 2, 3812, 381),
(3813, 'labor contract', '/ˈleɪbər ˈkɒntrækt/', 'noun', '{"zh-TW":["勞動合約"],"en":["a legal agreement defining terms of employment between employer and employee"]}', NULL, 'sign a labor contract / labor contract terms', '[{"en":"All new employees must sign a labor contract before starting.","zh-TW":"所有新員工在開始工作前必須簽署勞動合約。"},{"en":"The labor contract specifies salary, hours, and benefits.","zh-TW":"勞動合約規定了薪資、工時和福利。"}]', NULL, NULL, 5, 3813, NULL),
(3814, 'labor cost', '/ˈleɪbər kɒst/', 'noun', '{"zh-TW":["勞動成本；人工成本"],"en":["the total expense of employing workers, including wages and benefits"]}', NULL, 'reduce labor costs / labor cost per unit / increasing labor costs', '[{"en":"Automation helps reduce labor costs in high-volume manufacturing.","zh-TW":"自動化有助於降低大量製造中的勞動成本。"},{"en":"Rising labor costs prompted the company to relocate production.","zh-TW":"勞動成本上升促使公司遷移了生產地點。"}]', NULL, NULL, 4, 3814, NULL),
(3815, 'labor dispute', '/ˈleɪbər dɪˈspjuːt/', 'noun', '{"zh-TW":["勞資糾紛"],"en":["a conflict between employees and employers over work conditions or pay"]}', NULL, 'resolve a labor dispute / labor dispute arbitration', '[{"en":"The labor dispute was settled through mediation after three weeks.","zh-TW":"勞資糾紛在三週後通過調解解決了。"},{"en":"A prolonged labor dispute can disrupt operations and damage brand reputation.","zh-TW":"長期的勞資糾紛可能會擾亂運營並損害品牌聲譽。"}]', NULL, NULL, 5, 3815, NULL),
(3816, 'labor force', '/ˈleɪbər fɔːrs/', 'noun', '{"zh-TW":["勞動力；勞動人口"],"en":["the total number of people available and willing to work"]}', NULL, 'expand the labor force / skilled labor force', '[{"en":"A growing labor force drove economic expansion in the region.","zh-TW":"不斷增長的勞動力推動了該地區的經濟擴張。"},{"en":"The company needed to upskill its labor force to meet digital demands.","zh-TW":"公司需要提升其勞動力技能以滿足數位需求。"}]', NULL, NULL, 4, 3816, NULL),
(3817, 'labor law', '/ˈleɪbər lɔː/', 'noun', '{"zh-TW":["勞動法"],"en":["legislation governing the relationship between employers and employees"]}', NULL, 'comply with labor law / labor law regulations / labor law compliance', '[{"en":"The company updated its policies to comply with new labor laws.","zh-TW":"公司更新了其政策以遵守新勞動法。"},{"en":"Labor law violations can result in significant fines.","zh-TW":"違反勞動法可能導致重大罰款。"}]', '{"plural":"labor laws","alternative":"employment law"}', NULL, 3, 3817, NULL),
(3818, 'labor market', '/ˈleɪbər ˈmɑːrkɪt/', 'noun', '{"zh-TW":["勞動力市場"],"en":["the supply and demand for workers, determining wages and employment"]}', NULL, 'tight labor market / labor market reforms / labor market participation', '[{"en":"A tight labor market gives workers more bargaining power over wages.","zh-TW":"緊繃的勞動力市場賦予工人更多工資談判籌碼。"},{"en":"Labor market data is a key indicator of economic health.","zh-TW":"勞動力市場數據是衡量經濟健康的關鍵指標。"}]', NULL, NULL, 4, 3818, NULL),
(3819, 'labor productivity', '/ˈleɪbər ˌprɒdʌkˈtɪvɪti/', 'noun', '{"zh-TW":["勞動生產率"],"en":["the amount of output produced per unit of labor input"]}', NULL, 'increase labor productivity / labor productivity growth', '[{"en":"Investment in automation doubled labor productivity in three years.","zh-TW":"自動化投資在三年內使勞動生產率翻了一倍。"},{"en":"Labor productivity improvements reduce per-unit manufacturing costs.","zh-TW":"勞動生產率提高降低了製造業的單位成本。"}]', NULL, NULL, 5, 3819, NULL),
(3820, 'labor shortage', '/ˈleɪbər ˈʃɔːrtɪdʒ/', 'noun', '{"zh-TW":["勞動力短缺"],"en":["an insufficient supply of workers to meet demand"]}', NULL, 'cope with labor shortages / labor shortage impact', '[{"en":"Labor shortages pushed wages higher in the construction industry.","zh-TW":"勞動力短缺推動了建築業工資上漲。"},{"en":"Automation was introduced to offset the impact of labor shortages.","zh-TW":"引入自動化以抵消勞動力短缺的影響。"}]', NULL, NULL, 5, 3820, NULL),
(3821, 'laboratory', '/ləˈbɒrətɔːri/', 'noun', '{"zh-TW":["實驗室"],"en":["a room equipped for scientific experiments and research"]}', NULL, 'science laboratory / laboratory research', '[{"en":"Students conducted experiments in the chemistry laboratory.","zh-TW":"學生在化學實驗室進行了實驗。"},{"en":"The laboratory is equipped with the latest research instruments.","zh-TW":"實驗室配備了最新的研究儀器。"}]', '{"adjective":"laboratory","abbreviation":"lab"}', NULL, 4, 3821, NULL),
(3822, 'laborious', '/''ləˌbɔːriəs/', 'adjective', '{"zh-TW":["費力的；辛苦的"],"en":["requiring considerable effort and time; not easy or quick"]}', NULL, 'laborious process / laborious task / laborious work', '[{"en":"The laborious process of sorting thousands of documents took several weeks.","zh-TW":"整理數千份文件的繁瑣過程花費了幾個星期。"},{"en":"Manually entering all the data was laborious, but the results were accurate.","zh-TW":"手動輸入所有數據很費力，但結果是準確的。"}]', '{"adverb":"laboriously","noun":"laboriousness"}', NULL, 3, 3822, NULL),
(3823, 'labour law', '/ˈleɪbər lɔː/', 'noun', '{"zh-TW":["勞動法"],"en":["the body of law governing the rights and duties of employers and employees"]}', NULL, 'comply with labour law / labour law reform', '[{"en":"The company revised its employment policies to comply with new labour law changes.","zh-TW":"公司修訂了其就業政策以遵守新的勞動法變化。"},{"en":"Labour law protects workers from exploitation and unfair dismissal.","zh-TW":"勞動法保護工人免受剝削和不公平解僱。"}]', '{"synonym":"employment law"}', NULL, 4, 3823, NULL),
(3824, 'labour relations', '/ˈleɪbər rɪˈleɪʃənz/', 'noun', '{"zh-TW":["勞動關係"],"en":["the relationship between employers and employees, especially in relation to wages"]}', NULL, 'improve labour relations / labour relations policy', '[{"en":"Good labour relations reduce the risk of industrial action.","zh-TW":"良好的勞動關係降低了工業行動的風險。"},{"en":"The HR department oversees labour relations and employee welfare.","zh-TW":"人力資源部門負責監督勞動關係和員工福利。"}]', NULL, NULL, 5, 3824, NULL),
(3825, 'labour turnover', '/ˈleɪbər ˈtɜːrnoʊvər/', 'noun', '{"zh-TW":["勞動力流動率；員工離職率"],"en":["the rate at which employees leave and are replaced within an organization"]}', NULL, 'reduce labour turnover / high labour turnover', '[{"en":"High labour turnover increases recruitment and training costs.","zh-TW":"高勞動力流動率增加了招募和培訓成本。"},{"en":"Flexible work policies significantly reduced the company''s labour turnover.","zh-TW":"彈性工作政策顯著降低了公司的勞動力流動率。"}]', '{"synonym":"staff turnover"}', NULL, 5, 3825, NULL),
(3826, 'lack', '/læk/', 'noun', '{"zh-TW":["缺乏","缺乏；不足"],"en":["the state of being without something","the state of not having something"]}', '{"root":{"text":"lack","meaning":"want/deficiency (缺乏)"},"logic":"指不足或缺少某物的狀態。"}', 'lack of / for lack of / lack confidence; lack of experience/funding/resources', '[{"en":"The project failed due to lack of funding.","zh-TW":"專案因缺乏資金而失敗。"},{"en":"He lacks the experience for this role.","zh-TW":"他缺乏擔任這個角色的經驗。"},{"en":"The project failed due to a lack of funding.","zh-TW":"該項目因缺乏資金而失敗。"},{"en":"He lacks the experience needed for this role.","zh-TW":"他缺乏這個職位所需的經驗。"}]', '{"verb":"lack","adjective":"lacking","noun":"lack"}', NULL, 1, 3826, NULL),
(3827, 'lactic acid', '/''læktɪk ˌæsɪd/', 'noun', '{"zh-TW":["乳酸"],"en":["a chemical compound that builds up in the muscles during intense exercise, causing fatigue"]}', NULL, 'produce lactic acid / lactic acid buildup / clear lactic acid', '[{"en":"High-intensity exercise causes lactic acid to build up in muscles, leading to a burning sensation.","zh-TW":"高強度運動會導致肌肉中乳酸積聚，引起灼燒感。"},{"en":"Cooling down after exercise helps the body clear lactic acid from the muscles.","zh-TW":"運動後降溫有助於身體清除肌肉中的乳酸。"}]', '{"adjective":"lactic"}', NULL, 4, 3827, NULL),
(3828, 'lactose-free', '/ˈlæktoʊs friː/', 'adjective', '{"zh-TW":["無乳糖的"],"en":["not containing lactose, a sugar found in milk"]}', NULL, 'lactose-free milk / lactose-free option', '[{"en":"Lactose-free milk is available for guests with intolerances.","zh-TW":"無乳糖牛奶提供給有乳糖不耐症的賓客。"},{"en":"We have lactose-free options for each dessert.","zh-TW":"我們的每款甜點都有無乳糖選項。"}]', NULL, NULL, 4, 3828, NULL),
(3829, 'lady', '/ˈleɪdi/', 'noun', '{"zh-TW":["女士"],"en":["a polite word for a woman"]}', NULL, 'ladies and gentlemen / leading lady', '[{"en":"Ladies and gentlemen, welcome to the conference.","zh-TW":"各位女士先生，歡迎來到會議。"},{"en":"She is the leading lady of the industry.","zh-TW":"她是這個產業的領軍人物。"}]', '{"noun":"lady"}', NULL, 1, 3829, NULL),
(3830, 'lag', '/læɡ/', 'noun, verb', '{"zh-TW":["落後；延遲"],"en":["a delay or period of time between two events"]}', NULL, 'time lag / jet lag / lag behind', '[{"en":"There is often a lag between policy changes and results.","zh-TW":"政策變更和結果之間通常有時間差。"},{"en":"Our sales figures lag behind the competition.","zh-TW":"我們的銷售數字落後於競爭對手。"}]', '{"noun":"lag","verb":"lag"}', NULL, 1, 3830, NULL),
(3831, 'laissez-faire', '/ˌleɪseɪ ˈfeər/', 'adjective', '{"zh-TW":["自由放任的"],"en":["a policy of non-intervention by government in economic affairs"]}', NULL, 'laissez-faire economics / laissez-faire approach / laissez-faire management', '[{"en":"A laissez-faire approach to regulation was blamed for the financial crisis.","zh-TW":"自由放任的監管方式被認為是金融危機的原因之一。"},{"en":"Laissez-faire management gives employees autonomy but may lack direction.","zh-TW":"自由放任式管理給予員工自主性，但可能缺乏方向性。"}]', NULL, NULL, 5, 3831, NULL),
(3832, 'lake', '/leɪk/', 'noun', '{"zh-TW":["湖"],"en":["a large body of water surrounded by land"]}', NULL, 'lakeside / by the lake', '[{"en":"The resort is by the lake.","zh-TW":"度假村在湖邊。"},{"en":"The team-building event is at the lakeside.","zh-TW":"團建活動在湖畔舉行。"}]', '{"noun":"lake","noun2":"lakeside"}', NULL, 1, 3832, NULL),
(3833, 'land', '/lænd/', 'noun', '{"zh-TW":["土地；著陸"],"en":["an area of ground","to arrive on the ground"]}', NULL, 'land a deal / on land', '[{"en":"We landed a major contract.","zh-TW":"我們拿下了一個大合約。"},{"en":"They purchased land for the new office.","zh-TW":"他們為新辦公室購買了土地。"}]', '{"noun":"land","verb":"land","noun2":"landing","noun3":"landlord"}', NULL, 1, 3833, NULL),
(3834, 'land acquisition', '/lænd ˌækwɪˈzɪʃən/', 'noun', '{"zh-TW":["土地收購"],"en":["the process of obtaining land for development or investment"]}', NULL, 'approve land acquisition / land acquisition cost', '[{"en":"The land acquisition for the new factory cost 20 million.","zh-TW":"新工廠的土地收購花費了2000萬元。"},{"en":"Land acquisition is the first step in the real estate development process.","zh-TW":"土地收購是房地產開發流程的第一步。"}]', NULL, NULL, 5, 3834, NULL),
(3835, 'land degradation', '/lænd ˌdeɡrəˈdeɪʃən/', 'noun', '{"zh-TW":["土地退化"],"en":["the reduction in the productive capacity of land"]}', NULL, 'prevent land degradation / land degradation neutrality / reverse land degradation', '[{"en":"Unsustainable farming practices contribute to land degradation.","zh-TW":"不可持續的農業做法導致土地退化。"},{"en":"Land degradation affects food production and rural livelihoods.","zh-TW":"土地退化影響糧食生產和農村生計。"}]', '{"verb":"degrade","adjective":"degraded"}', NULL, 5, 3835, NULL),
(3836, 'land registry', '/lænd ˈredʒɪstri/', 'noun', '{"zh-TW":["土地登記處；產權登記處"],"en":["a government office maintaining official records of land ownership and charges"]}', NULL, 'register with the land registry / search the land registry', '[{"en":"The property purchase was completed after registration at the land registry.","zh-TW":"在土地登記處完成登記後，房產購買得以完成。"},{"en":"A land registry search confirms the current owner and any charges.","zh-TW":"土地登記搜索確認了當前所有者和任何產權負擔。"}]', NULL, NULL, 5, 3836, NULL),
(3837, 'land valuation', '/lænd ˌvæljuˈeɪʃən/', 'noun', '{"zh-TW":["土地估值"],"en":["the process of determining the monetary value of a piece of land"]}', NULL, 'conduct a land valuation / land valuation report', '[{"en":"An independent land valuation is required before a bank approves a mortgage.","zh-TW":"銀行批准抵押貸款之前需要進行獨立的土地估值。"},{"en":"Land valuation considers location, zoning, and comparable sales.","zh-TW":"土地估值考慮位置、分區和可比銷售情況。"}]', NULL, NULL, 5, 3837, NULL),
(3838, 'land value', '/lænd ˈvæljuː/', 'noun', '{"zh-TW":["地價；土地價值"],"en":["the monetary worth of a piece of land excluding structures on it"]}', NULL, 'assess land value / land value appreciation', '[{"en":"Rising land values increased the cost of urban development projects.","zh-TW":"上漲的地價增加了城市開發項目的成本。"},{"en":"Land value is a key factor in determining property investment returns.","zh-TW":"地價是決定房地產投資回報的關鍵因素。"}]', NULL, NULL, 4, 3838, NULL),
(3839, 'landed cost', '/ˈlændɪd kɒst/', 'noun', '{"zh-TW":["到岸成本；完稅成本"],"en":["the total cost of imported goods including shipping, insurance, and duties"]}', NULL, 'calculate landed cost / landed cost analysis', '[{"en":"The landed cost of the imported machinery was 20% above the factory price.","zh-TW":"進口機械的到岸成本比出廠價高出20%。"},{"en":"Understanding landed cost is essential for accurate product pricing.","zh-TW":"了解到岸成本對於準確的產品定價至關重要。"}]', NULL, NULL, 4, 3839, NULL),
(3840, 'landfill', '/ˈlændfɪl/', 'noun', '{"zh-TW":["垃圾掩埋場"],"en":["a site for the disposal of waste by burial"]}', NULL, 'reduce landfill waste / landfill gas', '[{"en":"Most household waste ends up in landfills.","zh-TW":"大多數家庭廢棄物最終進入垃圾掩埋場。"},{"en":"The city is working to divert waste away from landfills.","zh-TW":"市政府正致力於讓廢棄物不進入垃圾掩埋場。"}]', NULL, NULL, 3, 3840, NULL),
(3841, 'landing page', '/ˈlændɪŋ peɪdʒ/', 'noun', '{"zh-TW":["登陸頁；到達頁"],"en":["a standalone web page designed to convert visitors into leads or customers"]}', NULL, 'optimize landing page / landing page design / A/B test landing pages', '[{"en":"The landing page had a clear call to action and minimal distractions.","zh-TW":"登陸頁有清晰的行動號召且干擾極少。"},{"en":"A well-designed landing page can dramatically improve conversion rates.","zh-TW":"精心設計的登陸頁可以顯著提高轉換率。"}]', NULL, NULL, 4, 3841, NULL),
(3842, 'landlord', '/ˈlændlɔːrd/', 'noun', '{"zh-TW":["房東"],"en":["a person who rents land or property to others"]}', NULL, 'notify the landlord / landlord and tenant', '[{"en":"The landlord increased the rent by 10%.","zh-TW":"房東將租金提高了10%。"},{"en":"Please notify the landlord before moving out.","zh-TW":"搬出前請通知房東。"}]', '{"noun":"landlord, landlady"}', NULL, 3, 3842, NULL),
(3843, 'landmark', '/ˈlændmɑːrk/', 'noun, adjective', '{"zh-TW":["地標；里程碑"],"en":["an easily recognized feature; a significant event"]}', NULL, 'landmark decision/ruling/agreement', '[{"en":"The court made a landmark decision on privacy rights.","zh-TW":"法院就隱私權做出了里程碑式的裁決。"},{"en":"The tower is the city''s most famous landmark.","zh-TW":"這座塔是城市最著名的地標。"}]', '{"noun":"landmark"}', NULL, 3, 3843, NULL),
(3844, 'landmark building', '/''lændˌmɑːrk ˌbɪldɪŋ/', 'noun', '{"zh-TW":["地標建築"],"en":["a building or structure that is easily recognizable and often serves as a tourist attraction"]}', NULL, 'photograph a landmark building / iconic landmark building', '[{"en":"The Eiffel Tower is arguably the world''s most famous landmark building.","zh-TW":"埃菲爾鐵塔可以說是世界上最著名的地標建築。"},{"en":"The landmark building was featured on the city''s official tourism materials.","zh-TW":"這座地標建築出現在城市的官方旅遊資料上。"}]', NULL, NULL, 5, 3844, NULL),
(3845, 'landscape', '/ˈlændskeɪp/', 'noun', '{"zh-TW":["風景；景觀","景觀；局勢"],"en":["the visible features of an area of land","the visible features of an area; the general situation"]}', '{"root":{"text":"land","meaning":"land (土地)"},"suffix":{"text":"scape","meaning":"view (景色)"},"logic":"土地的景色，即「風景」。"}', 'landscape painting / urban landscape; political/business landscape / landscape design', '[{"en":"The landscape in this region is breathtaking.","zh-TW":"這個地區的風景令人嘆為觀止。"},{"en":"She specializes in landscape photography.","zh-TW":"她專精風景攝影。"},{"en":"The business landscape has changed dramatically.","zh-TW":"商業格局發生了巨大的變化。"},{"en":"The landscape of the countryside is breathtaking.","zh-TW":"鄉村的景觀令人歎為觀止。"}]', '{"noun":"landscaping","verb":"landscape"}', NULL, 3, 3845, NULL),
(3846, 'language', '/ˈlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["語言"],"en":["a system of communication"]}', NULL, 'body language / language barrier', '[{"en":"The language barrier made negotiations difficult.","zh-TW":"語言障礙使談判變得困難。"},{"en":"She speaks three languages fluently.","zh-TW":"她流利地說三種語言。"}]', '{"noun":"language","adjective":"linguistic","noun2":"linguistics"}', NULL, 3, 3846, NULL),
(3847, 'language acquisition', '/''læŋɡwɪdʒ əˌkwɪˈzɪʃən/', 'noun', '{"zh-TW":["語言習得；語言學習過程"],"en":["the process by which humans acquire the capacity to perceive and comprehend language"]}', NULL, 'study language acquisition / language acquisition theory / natural language acquisition', '[{"en":"Children go through a critical period for language acquisition before age twelve.","zh-TW":"兒童在十二歲之前會經歷語言習得的關鍵時期。"},{"en":"Research on language acquisition suggests that immersion is the fastest learning method.","zh-TW":"語言習得研究表明，沉浸式學習是最快的學習方法。"}]', '{"verb":"acquire"}', NULL, 5, 3847, NULL),
(3848, 'language barrier', '/''læŋɡwɪdʒ ˌbæriər/', 'noun', '{"zh-TW":["語言障礙"],"en":["a barrier to communication between people who speak different languages"]}', NULL, 'overcome a language barrier / language barrier challenge / break down language barriers', '[{"en":"The language barrier made it difficult to negotiate effectively with the foreign client.","zh-TW":"語言障礙使得與外國客戶進行有效談判變得困難。"},{"en":"Translation technology is helping businesses overcome language barriers globally.","zh-TW":"翻譯技術正在幫助企業克服全球語言障礙。"}]', NULL, NULL, 5, 3848, NULL),
(3849, 'laparoscopy', '/ˌlæpəˈrɒskəpi/', 'noun', '{"zh-TW":["腹腔鏡檢查"],"en":["a minimally invasive surgical procedure using a small camera"]}', NULL, 'perform laparoscopy / diagnostic laparoscopy / laparoscopy procedure', '[{"en":"Laparoscopy allows surgeons to operate through tiny incisions.","zh-TW":"腹腔鏡手術允許外科醫師通過微小切口進行手術。"},{"en":"The patient''s gallbladder was removed via laparoscopy.","zh-TW":"患者的膽囊通過腹腔鏡手術切除。"}]', '{"adjective":"laparoscopic","adverb":"laparoscopically"}', NULL, 4, 3849, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3850, 'large', '/lɑːrdʒ/', 'adjective', '{"zh-TW":["大的；大規模的"],"en":["big in size or amount"]}', NULL, 'at large / by and large', '[{"en":"By and large, the plan was successful.","zh-TW":"總的來說，計畫是成功的。"},{"en":"We serve large corporate clients.","zh-TW":"我們服務大型企業客戶。"}]', '{"adjective":"large","adverb":"largely","verb":"enlarge","noun":"enlargement"}', NULL, 2, 3850, NULL),
(3851, 'large-scale', '/lɑːrdʒ skeɪl/', 'adjective', '{"zh-TW":["大規模的"],"en":["involving a large number of people, resources, or activities"]}', NULL, 'large-scale operation / large-scale project / large-scale investment', '[{"en":"The large-scale infrastructure project required coordinated government support.","zh-TW":"大規模基礎設施項目需要協調一致的政府支持。"},{"en":"Large-scale manufacturing requires significant capital investment.","zh-TW":"大規模製造需要大量的資本投資。"}]', NULL, NULL, 4, 3851, NULL),
(3852, 'largesse', '/lɑːrˈdʒes/', 'noun', '{"zh-TW":["慷慨；慷慨捐贈"],"en":["generosity in bestowing money or gifts upon others"]}', NULL, 'corporate largesse / political largesse / distribute largesse', '[{"en":"The billionaire''s largesse funded dozens of arts institutions across the country.","zh-TW":"這位億萬富翁的慷慨資助了全國數十個藝術機構。"},{"en":"Political largesse through government contracts rewarded campaign donors.","zh-TW":"通過政府合同進行的政治慷慨回報了競選捐助者。"}]', NULL, NULL, 3, 3852, NULL),
(3853, 'last', '/lɑːst/', 'adjective', '{"zh-TW":["最後的；上一個；持續"],"en":["coming after all others","most recent","to continue"]}', NULL, 'at last / last resort', '[{"en":"As a last resort, we may outsource.","zh-TW":"作為最後手段，我們可能外包。"},{"en":"The meeting lasted two hours.","zh-TW":"會議持續了兩個小時。"}]', '{"adjective":"last","verb":"last","adverb":"lastly","adjective2":"lasting"}', NULL, 1, 3853, NULL),
(3854, 'last-mile delivery', '/lɑːst maɪl dɪˈlɪvəri/', 'noun', '{"zh-TW":["最後一哩配送"],"en":["the final step of the delivery process from distribution center to end customer"]}', NULL, 'optimize last-mile delivery / last-mile delivery solution', '[{"en":"Last-mile delivery accounts for most of the total shipping cost.","zh-TW":"最後一哩配送佔總運費的大部分。"},{"en":"Drone technology aims to revolutionize last-mile delivery.","zh-TW":"無人機技術旨在革新最後一哩配送。"}]', NULL, NULL, 5, 3854, NULL),
(3855, 'late', '/leɪt/', 'adjective', '{"zh-TW":["遲的；晚的"],"en":["after the expected time","near the end"]}', NULL, 'too late / late fee', '[{"en":"A late fee will be charged after the due date.","zh-TW":"逾期將收取滯納金。"},{"en":"Sorry I am late for the meeting.","zh-TW":"抱歉我開會遲到了。"}]', '{"adjective":"late","adverb":"lately","adverb2":"late","noun":"lateness"}', NULL, 1, 3855, NULL),
(3856, 'late arrival', '/leɪt əˈraɪvəl/', 'noun', '{"zh-TW":["晚到；夜間入住"],"en":["arriving at a hotel after normal check-in hours"]}', NULL, 'notify of a late arrival / late arrival note', '[{"en":"Please inform the hotel of a late arrival to secure the room.","zh-TW":"請通知飯店晚到情況，以確保房間不被取消。"},{"en":"A note was left for the late arrival guest at the front desk.","zh-TW":"前台為晚到的賓客留了一張便條。"}]', NULL, NULL, 4, 3856, NULL),
(3857, 'late checkout', '/''leɪt ˌtʃekˈaʊt/', 'noun', '{"zh-TW":["延遲退房；晚退房"],"en":["checking out of a hotel after the standard checkout time, usually for an extra fee"]}', NULL, 'request late checkout / late checkout fee / arrange late checkout', '[{"en":"She requested a late checkout to have more time to pack her luggage.","zh-TW":"她要求延遲退房，以有更多時間收拾行李。"},{"en":"Late checkout is often available for loyalty program members at no charge.","zh-TW":"延遲退房通常對忠誠度計畫會員免費提供。"}]', NULL, NULL, 5, 3857, NULL),
(3858, 'late payment', '/leɪt ˈpeɪmənt/', 'noun', '{"zh-TW":["逾期付款"],"en":["payment made after the due date"]}', NULL, 'chase late payments / late payment penalty', '[{"en":"Late payments by clients disrupted the company cash flow.","zh-TW":"客戶的逾期付款擾亂了公司的現金流。"},{"en":"A late payment fee of 2% per month is applied after 30 days.","zh-TW":"逾期付款後30天起按每月2%計算滯納金。"}]', NULL, NULL, 4, 3858, NULL),
(3859, 'late payment penalty', '/leɪt ˈpeɪmənt ˈpenəlti/', 'noun', '{"zh-TW":["逾期付款罰款"],"en":["a fee charged for making a payment after the agreed due date"]}', NULL, 'apply a late payment penalty / late payment penalty clause', '[{"en":"The contract specifies a 2% late payment penalty on overdue invoices.","zh-TW":"合約規定對逾期發票收取2%的逾期付款罰款。"},{"en":"Clients received warnings before the late payment penalty was applied.","zh-TW":"在收取逾期付款罰款前向客戶發出了警告。"}]', NULL, NULL, 5, 3859, NULL),
(3860, 'latency', '/ˈleɪtənsi/', 'noun', '{"zh-TW":["延遲；潛伏期"],"en":["the time delay between a request and the response in a system"]}', NULL, 'reduce latency / network latency / low-latency system', '[{"en":"High latency degrades the user experience in real-time applications.","zh-TW":"高延遲會降低即時應用程式的用戶體驗。"},{"en":"Caching and CDN usage are common strategies to reduce latency.","zh-TW":"快取和CDN使用是減少延遲的常見策略。"}]', '{"adjective":"latent"}', NULL, 3, 3860, NULL),
(3861, 'latent', '/ˈleɪtənt/', 'adjective', '{"zh-TW":["潛伏的；潛在的"],"en":["existing but not yet developed or manifest"]}', NULL, 'latent demand / latent talent / latent infection', '[{"en":"The new product revealed latent consumer demand for portable electronics.","zh-TW":"這款新產品揭示了消費者對便攜式電子產品的潛在需求。"},{"en":"A latent infection may remain dormant for years before causing symptoms.","zh-TW":"潛伏感染可能在多年後才出現症狀。"}]', '{"adverb":"latently","noun":"latency"}', NULL, 2, 3861, NULL),
(3862, 'lateral thinking', '/ˈlætərəl ˈθɪŋkɪŋ/', 'noun', '{"zh-TW":["橫向思維；側向思維"],"en":["solving problems through an indirect and creative approach"]}', NULL, 'apply lateral thinking / lateral thinking skills / encourage lateral thinking', '[{"en":"Lateral thinking breaks conventional problem-solving patterns to find new solutions.","zh-TW":"橫向思維打破傳統的問題解決模式以找到新的解決方案。"},{"en":"The workshop encouraged lateral thinking to generate innovative ideas.","zh-TW":"研討會鼓勵橫向思維以產生創新想法。"}]', NULL, NULL, 5, 3862, NULL),
(3863, 'latest', 'ˈleɪtɪst', 'adjective', '{"zh-TW":["最新的；最近的","最晚的"],"en":["most recent","up to date"]}', NULL, 'latest version/latest news', '[{"en":"Please download the latest version.","zh-TW":"請下載最新版本。"}]', '{"adverb":"lately"}', NULL, 2, 3863, NULL),
(3864, 'latitude', '/ˈlætɪtjuːd/', 'noun', '{"zh-TW":["【主要意義】緯度","【次要意義】自由度；寬容度；行動或表達的自由空間"],"en":["[primary] the distance north or south of the equator","[secondary] freedom from restrictions; scope for action or thought"]}', NULL, 'give someone latitude / allow latitude / considerable latitude', '[{"en":"The manager gave her team considerable latitude in choosing their approach.","zh-TW":"經理給了她的團隊相當大的自由度來選擇他們的方法。"},{"en":"Journalists need latitude to investigate without interference.","zh-TW":"記者需要在不受干擾的情況下進行調查的自由度。"},{"en":"The new policy allows employees more latitude in their work schedules.","zh-TW":"新政策給予員工在工作時間安排上更多的靈活度。"}]', '{"adjective":"latitudinal"}', '除地理上的「緯度」外，latitude 在商業或管理語境中指「靈活度/自由裁量空間」，TOEIC 閱讀測驗中常見於描述管理或決策的文章。', 3, 3864, NULL),
(3865, 'laugh', '/læf/', 'verb', '{"zh-TW":["笑"],"en":["to make sounds showing amusement"]}', NULL, 'laugh at / have a laugh', '[{"en":"Don''t laugh at others'' mistakes.","zh-TW":"不要嘲笑別人的錯誤。"},{"en":"We had a good laugh at the team dinner.","zh-TW":"我們在團隊晚餐上笑得很開心。"}]', '{"verb":"laugh","noun":"laugh","noun2":"laughter"}', NULL, 2, 3865, NULL),
(3866, 'launch', '/lɔːntʃ/', 'verb', '{"zh-TW":["推出；發射","發射；推出；發起"],"en":["to start or introduce something new","to send into the air","to start or introduce something new; to send into the air"]}', '{"root":{"text":"launch","meaning":"throw (投擲)"},"logic":"源自古法語 lanchier（投擲），指推出新事物。"}', 'launch a product / launch a campaign / rocket launch; launch a product/campaign/website', '[{"en":"The company will launch a new product next week.","zh-TW":"公司下週將推出新產品。"},{"en":"NASA launched a satellite into orbit.","zh-TW":"NASA發射了一顆衛星進入軌道。"},{"en":"The company will launch its new product next month.","zh-TW":"公司將於下個月推出新產品。"},{"en":"They launched a marketing campaign on social media.","zh-TW":"他們在社群媒體上發起了行銷活動。"}]', '{"noun":"launch","verb":"launch"}', NULL, 2, 3866, 148),
(3867, 'launch campaign', '/lɔːntʃ kæmˈpeɪn/', 'noun', '{"zh-TW":["發布活動；推廣活動"],"en":["a marketing campaign designed to introduce a new product or service"]}', NULL, 'run a launch campaign / launch campaign budget', '[{"en":"The launch campaign for the new product generated 10000 pre-orders.","zh-TW":"新產品的發布活動產生了1萬個預訂。"},{"en":"The launch campaign targeted social media to reach younger consumers.","zh-TW":"發布活動針對社交媒體觸及年輕消費者。"}]', NULL, NULL, 5, 3867, NULL),
(3868, 'launch date', '/lɔːntʃ deɪt/', 'noun', '{"zh-TW":["發布日期；上市日期"],"en":["the scheduled day on which a product, service, or campaign is introduced"]}', NULL, 'confirm the launch date / delay the launch date', '[{"en":"The launch date was moved forward to capture the holiday shopping season.","zh-TW":"發布日期提前以抓住假日購物季節。"},{"en":"Marketing materials must be ready two weeks before the launch date.","zh-TW":"行銷材料必須在發布日期前兩週準備就緒。"}]', NULL, NULL, 4, 3868, NULL),
(3869, 'launch strategy', '/lɔːntʃ ˈstrætədʒi/', 'noun', '{"zh-TW":["發佈策略；上市策略"],"en":["the plan for introducing a new product or service to the market"]}', NULL, 'develop a launch strategy / execute the launch strategy', '[{"en":"The launch strategy focused on digital channels and influencer marketing.","zh-TW":"發佈策略聚焦於數位渠道和網紅行銷。"},{"en":"A phased launch strategy reduces risk in unfamiliar markets.","zh-TW":"分階段的上市策略降低了在陌生市場的風險。"}]', NULL, NULL, 5, 3869, NULL),
(3870, 'laundry service', '/ˈlɔːndri ˈsɜːrvɪs/', 'noun', '{"zh-TW":["洗衣服務"],"en":["a service for washing and ironing clothes"]}', NULL, 'use the laundry service / same-day laundry service', '[{"en":"The hotel provides a same-day laundry service.","zh-TW":"飯店提供當天洗衣服務。"},{"en":"Please fill out the laundry form in your room.","zh-TW":"請填寫房間內的洗衣單。"}]', NULL, NULL, 5, 3870, NULL),
(3871, 'law', '/lɔː/', 'noun', '{"zh-TW":["法律；法規"],"en":["rules made by a government"]}', NULL, 'break/obey the law / by law / law firm', '[{"en":"It is against the law to discriminate based on gender.","zh-TW":"基於性別的歧視是違法的。"},{"en":"She works for a prestigious law firm.","zh-TW":"她在一家知名律師事務所工作。"}]', '{"noun":"law, lawyer, lawsuit","adjective":"lawful, legal"}', NULL, 1, 3871, NULL),
(3872, 'lawsuit', '/ˈlɔːsuːt/', 'noun', '{"zh-TW":["訴訟"],"en":["a legal case brought to court"]}', NULL, 'file a lawsuit / class-action lawsuit', '[{"en":"She filed a lawsuit against the company.","zh-TW":"她對公司提起了訴訟。"},{"en":"The lawsuit was settled out of court.","zh-TW":"訴訟在庭外和解了。"}]', NULL, NULL, 3, 3872, NULL),
(3873, 'layoff', '/ˈleɪɒf/', 'noun', '{"zh-TW":["裁員；暫時解雇"],"en":["the temporary or permanent termination of employee jobs"]}', NULL, 'mass layoff / layoff announcement / avoid layoffs', '[{"en":"The company announced layoffs affecting 10% of its workforce.","zh-TW":"公司宣布裁員，影響10%的員工。"},{"en":"Thousands of employees received layoff notices last week.","zh-TW":"上週數千名員工收到了裁員通知。"}]', '{"verb":"lay off"}', NULL, 2, 3873, NULL),
(3874, 'layoff notice', '/ˈleɪɒf ˈnoʊtɪs/', 'noun', '{"zh-TW":["裁員通知"],"en":["formal written notification given to employees being made redundant"]}', NULL, 'issue a layoff notice / receive a layoff notice', '[{"en":"Employees received their layoff notices with four weeks advance warning.","zh-TW":"員工提前四週收到了裁員通知。"},{"en":"A layoff notice must include details of severance and appeal rights.","zh-TW":"裁員通知必須包括遣散費和上訴權的詳情。"}]', NULL, NULL, 5, 3874, NULL),
(3875, 'layout', '/ˈleɪaʊt/', 'noun', '{"zh-TW":["佈局；版面設計"],"en":["the way things are arranged in a space"]}', NULL, 'office layout / page layout / floor layout', '[{"en":"The office layout was redesigned for better collaboration.","zh-TW":"辦公室佈局被重新設計以促進更好的合作。"},{"en":"She designed the layout of the new brochure.","zh-TW":"她設計了新宣傳冊的版面。"}]', '{"noun":"layout","verb":"lay out"}', NULL, 2, 3875, NULL),
(3876, 'layover', '/ˈleɪoʊvər/', 'noun', '{"zh-TW":["中途停留；過境停留"],"en":["a period of rest during a journey"]}', NULL, 'short layover / overnight layover', '[{"en":"We have a four-hour layover in Frankfurt.","zh-TW":"我們在法蘭克福有四小時的過境停留。"},{"en":"Use your layover to explore the city.","zh-TW":"利用過境停留時間遊覽城市。"}]', NULL, NULL, 3, 3876, NULL),
(3877, 'lead', '/liːd/', 'verb, noun', '{"zh-TW":["領導；帶領","領先；主導地位"],"en":["to guide or direct; to be in charge","a position of advantage"]}', NULL, 'lead a team/project / take the lead', '[{"en":"She leads a team of ten engineers.","zh-TW":"她領導一個十人的工程師團隊。"},{"en":"Our company has taken the lead in innovation.","zh-TW":"我們公司在創新方面處於領先地位。"}]', '{"noun":"lead, leader, leadership","verb":"lead","adjective":"leading"}', NULL, 1, 3877, NULL),
(3878, 'lead generation', '/liːd ˌdʒenəˈreɪʃən/', 'noun', '{"zh-TW":["潛在客戶開發"],"en":["the process of attracting and converting prospects into potential customers"]}', NULL, 'lead generation strategy / lead generation campaign / B2B lead generation', '[{"en":"Content marketing is effective for lead generation.","zh-TW":"內容行銷對潛在客戶開發很有效。"},{"en":"The lead generation campaign added 500 prospects to the pipeline.","zh-TW":"潛在客戶開發活動為銷售漏斗增加了500個潛在客戶。"}]', '{"verb":"generate leads"}', NULL, 5, 3878, NULL),
(3879, 'lead nurturing', '/liːd ˈnɜːrtʃərɪŋ/', 'noun', '{"zh-TW":["潛在客戶培育"],"en":["building relationships with potential customers at every stage of the funnel"]}', NULL, 'lead nurturing campaign / lead nurturing strategy / automated lead nurturing', '[{"en":"Lead nurturing emails guide prospects through the buying journey.","zh-TW":"潛在客戶培育電子郵件引導潛在客戶完成購買旅程。"},{"en":"Personalized lead nurturing improves conversion rates significantly.","zh-TW":"個人化潛在客戶培育顯著提高了轉換率。"}]', '{"verb":"nurture leads"}', NULL, 5, 3879, NULL),
(3880, 'lead time', '/liːd taɪm/', 'noun', '{"zh-TW":["前置時間；交貨時間"],"en":["the time between initiating a process and its completion"]}', NULL, 'reduce lead time / lead time of two weeks / manufacturing lead time', '[{"en":"The supplier''s lead time was reduced from six weeks to two.","zh-TW":"供應商的前置時間從六週縮短至兩週。"},{"en":"Short lead times give manufacturers flexibility to respond to demand.","zh-TW":"短前置時間使製造商能靈活應對需求。"}]', NULL, NULL, 3, 3880, NULL),
(3881, 'lead time reduction', '/liːd taɪm rɪˈdʌkʃən/', 'noun', '{"zh-TW":["縮短前置時間"],"en":["decreasing the time between order placement and delivery"]}', NULL, 'achieve lead time reduction / lead time reduction initiative', '[{"en":"Lead time reduction was a key goal of the supply chain project.","zh-TW":"縮短前置時間是供應鏈項目的關鍵目標。"},{"en":"Closer collaboration with suppliers enabled significant lead time reduction.","zh-TW":"與供應商更緊密的合作實現了顯著的前置時間縮短。"}]', NULL, NULL, 5, 3881, NULL),
(3882, 'leadership', '/ˈliːdərʃɪp/', 'noun', '{"zh-TW":["領導力；領導層"],"en":["the quality of being a leader; the group of leaders"]}', NULL, 'strong leadership / leadership skills / under the leadership of', '[{"en":"Strong leadership is essential for organizational success.","zh-TW":"強有力的領導對組織成功至關重要。"},{"en":"Under her leadership, the company doubled its revenue.","zh-TW":"在她的領導下，公司收入翻了一番。"}]', '{"noun":"leadership, leader","verb":"lead","adjective":"leading"}', NULL, 4, 3882, 382),
(3883, 'leadership development', '/ˈliːdərʃɪp dɪˈveləpmənt/', 'noun', '{"zh-TW":["領導力發展"],"en":["programs designed to build management and leadership skills"]}', NULL, 'invest in leadership development / leadership development program', '[{"en":"The company invests in leadership development for high-potential employees.","zh-TW":"公司為高潛力員工投資領導力發展。"},{"en":"Leadership development programs improve succession planning outcomes.","zh-TW":"領導力發展計劃改善了繼任規劃成果。"}]', NULL, NULL, 5, 3883, NULL),
(3884, 'leadership pipeline', '/ˈliːdəʃɪp ˈpaɪplaɪn/', 'noun', '{"zh-TW":["領導力培育通道"],"en":["a systematic approach to developing future leaders in an organization"]}', NULL, 'build a leadership pipeline / maintain a leadership pipeline / leadership pipeline development', '[{"en":"A strong leadership pipeline ensures continuity during management transitions.","zh-TW":"強健的領導力培育通道確保管理層過渡期間的連續性。"},{"en":"Succession planning relies on a well-developed leadership pipeline.","zh-TW":"接班人計劃依賴於發展完善的領導力培育通道。"}]', NULL, NULL, 5, 3884, NULL),
(3885, 'league', '/liːɡ/', 'noun', '{"zh-TW":["聯盟；聯賽"],"en":["a group of sports teams that compete"]}', NULL, 'major league / out of one''s league', '[{"en":"He plays in the major leagues.","zh-TW":"他在大聯盟打球。"},{"en":"That restaurant is out of my league.","zh-TW":"那家餐廳不是我消費得起的。"}]', NULL, NULL, 2, 3885, NULL),
(3886, 'lean', '/liːn/', 'adjective, verb', '{"zh-TW":["精簡的；瘦的","傾斜；依靠"],"en":["thin; efficient with minimal waste","to incline or rest against"]}', NULL, 'lean manufacturing / lean budget / lean on', '[{"en":"The company adopted lean manufacturing practices.","zh-TW":"公司採用了精實生產方式。"},{"en":"We need to run a lean operation to survive.","zh-TW":"我們需要精簡營運才能生存。"}]', '{"noun":"lean","adjective":"lean","verb":"lean"}', NULL, 1, 3886, NULL),
(3887, 'lean inventory', '/liːn ɪnˈventɔːri/', 'noun', '{"zh-TW":["精益庫存"],"en":["keeping only the minimum amount of stock necessary to meet demand"]}', NULL, 'maintain lean inventory / lean inventory approach', '[{"en":"A lean inventory approach reduces holding costs and waste.","zh-TW":"精益庫存方式降低了持有成本和浪費。"},{"en":"Technology helps companies maintain lean inventory without stockouts.","zh-TW":"技術幫助公司在不缺貨的情況下維持精益庫存。"}]', NULL, NULL, 5, 3887, NULL),
(3888, 'lean management', '/liːn ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["精益管理"],"en":["a management approach focused on eliminating waste"]}', NULL, 'lean management principles / lean management system', '[{"en":"Lean management helped the factory cut production waste by 30%.","zh-TW":"精益管理幫助工廠將生產浪費削減了30%。"},{"en":"They implemented lean management to improve workflow.","zh-TW":"他們實施精益管理以改善工作流程。"}]', '{"adjective":"lean"}', NULL, 5, 3888, NULL),
(3889, 'lean manufacturing', '/liːn ˌmænjʊˈfæktʃərɪŋ/', 'noun', '{"zh-TW":["精益生產"],"en":["a production method focused on minimizing waste and maximizing value"]}', NULL, 'implement lean manufacturing / lean manufacturing principles', '[{"en":"Lean manufacturing reduced waste by 40% in the first year.","zh-TW":"精益生產在第一年將浪費減少了40%。"},{"en":"Lean manufacturing principles are widely used in automotive production.","zh-TW":"精益生產原則在汽車製造中被廣泛應用。"}]', NULL, NULL, 5, 3889, NULL),
(3890, 'learn', '/lɜːrn/', 'verb', '{"zh-TW":["學習；得知"],"en":["to gain knowledge","to find out"]}', NULL, 'learn from / learn the ropes', '[{"en":"We learn from our mistakes.","zh-TW":"我們從錯誤中學習。"},{"en":"It takes time to learn the ropes.","zh-TW":"熟悉工作需要時間。"}]', '{"verb":"learn","noun":"learner","noun2":"learning","adjective":"learned"}', NULL, 2, 3890, NULL),
(3891, 'learning', 'ˈlɜːrnɪŋ', 'noun', '{"zh-TW":["學習；知識","學識"],"en":["the acquisition of knowledge","skills gained through study"]}', NULL, 'continuous learning/learning curve', '[{"en":"Continuous learning is encouraged here.","zh-TW":"這裡鼓勵持續學習。"}]', '{"verb":"learn","adjective":"learned"}', NULL, 3, 3891, NULL),
(3892, 'learning disability', '/''lɜːrnɪŋ dɪsˌæbɪlɪti/', 'noun', '{"zh-TW":["學習障礙"],"en":["a condition that makes it difficult for a person to learn in a typical manner"]}', NULL, 'diagnosed with a learning disability / support for learning disability / manage a learning disability', '[{"en":"Students with a learning disability may receive additional support and accommodations.","zh-TW":"有學習障礙的學生可能會獲得額外的支持和特殊安排。"},{"en":"Early identification of a learning disability helps children get the right support.","zh-TW":"早期識別學習障礙有助於兒童獲得正確的支持。"}]', NULL, NULL, 5, 3892, NULL),
(3893, 'learning outcome', '/''lɜːrnɪŋ ˌaʊtkʌm/', 'noun', '{"zh-TW":["學習成果；學習目標"],"en":["a specific statement of what a student should be able to do or understand after completing a course"]}', NULL, 'define learning outcomes / achieve learning outcomes / measure learning outcomes', '[{"en":"The course outlines specific learning outcomes that students will achieve.","zh-TW":"課程概述了學生將達到的具體學習成果。"},{"en":"Assessments are designed to measure whether students have met the learning outcomes.","zh-TW":"評量設計用來衡量學生是否達到了學習成果。"}]', NULL, NULL, 5, 3893, NULL),
(3894, 'lease', '/liːs/', 'noun, verb', '{"zh-TW":["租約；租賃"],"en":["a contract to use property for a specified time"]}', NULL, 'sign/renew a lease / lease agreement', '[{"en":"The office lease expires at the end of the year.","zh-TW":"辦公室租約年底到期。"},{"en":"We leased the equipment for three years.","zh-TW":"我們租賃了設備三年。"}]', '{"noun":"lease, leaseholder","verb":"lease"}', NULL, 2, 3894, 149),
(3895, 'lease agreement', '/liːs əˈɡriːmənt/', 'noun', '{"zh-TW":["租約；租賃協議"],"en":["a contract between a landlord and tenant setting out lease terms"]}', NULL, 'sign a lease agreement / renew a lease agreement / lease agreement terms', '[{"en":"The lease agreement runs for five years with renewal options.","zh-TW":"租約為期五年，並有續約選擇權。"},{"en":"The lease agreement specifies rent, maintenance responsibilities, and notice periods.","zh-TW":"租約規定了租金、維護責任和通知期。"}]', '{"plural":"lease agreements"}', NULL, 5, 3895, NULL),
(3896, 'lease extension', '/liːs ɪkˈstenʃən/', 'noun', '{"zh-TW":["租約延期"],"en":["the prolongation of an existing lease for a further period"]}', NULL, 'negotiate a lease extension / agree to a lease extension', '[{"en":"The tenant negotiated a two-year lease extension at favorable terms.","zh-TW":"租客以有利條款談判了兩年的租約延期。"},{"en":"A lease extension avoids the disruption of finding new premises.","zh-TW":"租約延期避免了尋找新場所的麻煩。"}]', NULL, NULL, 5, 3896, NULL),
(3897, 'lease renewal', '/liːs rɪˈnjuːəl/', 'noun', '{"zh-TW":["租約續租"],"en":["the extension of a lease agreement for a new period under agreed conditions"]}', NULL, 'negotiate a lease renewal / lease renewal terms', '[{"en":"The tenant negotiated a lease renewal at a 5% reduced rental rate.","zh-TW":"租戶談判了以5%降低租金的租約續租。"},{"en":"Advance planning for lease renewal prevents gaps in business premises.","zh-TW":"提前規劃租約續租防止了業務場所的空缺。"}]', NULL, NULL, 5, 3897, NULL),
(3898, 'leasehold', '/ˈliːshəʊld/', 'noun', '{"zh-TW":["租賃產權；租賃持有"],"en":["the holding of property on a long-term lease"]}', NULL, 'leasehold property / leasehold agreement', '[{"en":"The company occupies the office on a leasehold basis.","zh-TW":"公司以租賃產權方式佔用辦公室。"},{"en":"Leasehold agreements typically run for 99 years.","zh-TW":"租賃產權協議通常持續99年。"}]', '{"adjective":"leasehold"}', NULL, 3, 3898, NULL),
(3899, 'leasehold improvement', '/ˈliːshoʊld ɪmˈpruːvmənt/', 'noun', '{"zh-TW":["租賃改良；裝修投資"],"en":["a modification made by a tenant to a rented property to make it more suitable"]}', NULL, 'capitalize leasehold improvements / depreciate leasehold improvements', '[{"en":"The company spent $300,000 on leasehold improvements to fit out the new office.","zh-TW":"公司花費了30萬元對新辦公室進行了租賃改良。"},{"en":"Leasehold improvements are amortized over the lease term or useful life.","zh-TW":"租賃改良在租賃期或有效使用年限內進行攤銷。"}]', NULL, NULL, 5, 3899, NULL);
