(3900, 'leave', '/liːv/', 'noun, verb', '{"zh-TW":["假期；休假","離開"],"en":["time when you are allowed to be away from work","to go away from"]}', NULL, 'on leave / sick leave / maternity leave', '[{"en":"She is on maternity leave until March.","zh-TW":"她休產假到三月。"},{"en":"He took a leave of absence for personal reasons.","zh-TW":"他因個人原因請了假。"}]', '{"noun":"leave","verb":"leave"}', NULL, 2, 3900, NULL),
(3901, 'lecture', '/ˈlɛktʃər/', 'noun', '{"zh-TW":["講座；演講"],"en":["a talk given to teach people","an educational talk to an audience"]}', NULL, 'attend a lecture / give a lecture; give/attend a lecture / lecture hall', '[{"en":"The professor gave an interesting lecture.","zh-TW":"教授做了一場有趣的演講。"},{"en":"I have a lecture at 2 PM.","zh-TW":"我下午2點有一堂課。"},{"en":"Professor Smith gave a lecture on economics.","zh-TW":"史密斯教授做了一場經濟學講座。"},{"en":"The lecture was attended by over 200 students.","zh-TW":"超過200名學生參加了講座。"}]', '{"verb":"lecture","noun2":"lecturer","noun":"lecture, lecturer"}', NULL, 3, 3901, NULL),
(3902, 'lecture hall', '/''lektʃər hɔːl/', 'noun', '{"zh-TW":["演講廳；大講堂"],"en":["a large room in a university or college equipped for lectures"]}', NULL, 'fill the lecture hall / lecture hall capacity / modern lecture hall', '[{"en":"The keynote speaker addressed over five hundred students in the lecture hall.","zh-TW":"主講人在演講廳向五百多名學生發表演講。"},{"en":"The new lecture hall was equipped with the latest audio-visual technology.","zh-TW":"新的演講廳配備了最新的視聽技術。"}]', NULL, NULL, 4, 3902, NULL),
(3903, 'lecture notes', '/''lektʃər nəʊts/', 'noun', '{"zh-TW":["課堂筆記；講義"],"en":["notes taken during or prepared for a lecture"]}', NULL, 'take lecture notes / review lecture notes / share lecture notes', '[{"en":"She organized her lecture notes into a clear outline before studying.","zh-TW":"她在學習前將課堂筆記整理成清晰的大綱。"},{"en":"Reviewing lecture notes within twenty-four hours significantly improves retention.","zh-TW":"在二十四小時內複習課堂筆記可以顯著提高記憶保留率。"}]', NULL, NULL, 5, 3903, NULL),
(3904, 'lecturer', '/''lektʃərər/', 'noun', '{"zh-TW":["講師；大學講師"],"en":["a person who gives lectures, especially one employed in a college or university"]}', NULL, 'university lecturer / guest lecturer / experienced lecturer', '[{"en":"The lecturer explained the concept clearly with real-world examples.","zh-TW":"講師用現實例子清楚地解釋了這個概念。"},{"en":"She became a lecturer after completing her doctoral degree.","zh-TW":"她在完成博士學位後成為了一名講師。"}]', '{"verb":"lecture","noun2":"lecture"}', NULL, 3, 3904, NULL),
(3905, 'ledger', '/ˈlɛdʒər/', 'noun', '{"zh-TW":["帳本；分類帳"],"en":["a book or digital record of all financial transactions"]}', NULL, 'general ledger / ledger entry / accounts ledger', '[{"en":"All transactions are posted to the general ledger.","zh-TW":"所有交易都過帳至總分類帳。"},{"en":"The bookkeeper reconciled the ledger at month-end.","zh-TW":"簿記員在月底對帳本進行了核對。"}]', '{"plural":"ledgers"}', NULL, 2, 3905, NULL),
(3906, 'leg room', '/''leɡ ruːm/', 'noun', '{"zh-TW":["腿部空間"],"en":["the space available for a seated person''s legs, especially in an aircraft or vehicle"]}', NULL, 'limited leg room / extra leg room / premium leg room', '[{"en":"Business class seats offer much more leg room than economy.","zh-TW":"商務艙座位提供比經濟艙多得多的腿部空間。"},{"en":"Tall passengers often pay extra to get seats with more leg room.","zh-TW":"高個子乘客通常會付額外費用選擇腿部空間更大的座位。"}]', NULL, NULL, 3, 3906, NULL),
(3907, 'legal', '/ˈliːɡl/', 'adjective', '{"zh-TW":["法律的；合法的"],"en":["relating to law; permitted by law"]}', NULL, 'legal advice/action/requirement', '[{"en":"You should seek legal advice before signing.","zh-TW":"簽署前你應該尋求法律建議。"},{"en":"The company took legal action against the competitor.","zh-TW":"公司對競爭對手提起了法律訴訟。"}]', '{"noun":"legality","adjective":"legal, illegal","adverb":"legally","verb":"legalize"}', NULL, 2, 3907, 383),
(3908, 'legal advisor', '/ˈliːɡəl ədˈvaɪzər/', 'noun', '{"zh-TW":["法律顧問"],"en":["a qualified lawyer who advises an organization on legal matters"]}', NULL, 'hire a legal advisor / consult a legal advisor', '[{"en":"The company retained a legal advisor to review the acquisition.","zh-TW":"公司聘請了法律顧問審查收購事宜。"},{"en":"A legal advisor confirmed the contract terms were enforceable.","zh-TW":"法律顧問確認合約條款具有可執行性。"}]', NULL, NULL, 5, 3908, NULL),
(3909, 'legal compliance', '/ˈliːɡəl kəmˈplaɪəns/', 'noun', '{"zh-TW":["法律合規"],"en":["adherence to laws, regulations, and standards applicable to a business"]}', NULL, 'ensure legal compliance / legal compliance review', '[{"en":"The company appointed a legal compliance team to monitor regulatory changes.","zh-TW":"公司指派了一個法律合規團隊來監控法規變化。"},{"en":"Failure to maintain legal compliance can result in fines and reputational damage.","zh-TW":"未能維持法律合規可能導致罰款和聲譽損害。"}]', NULL, NULL, 5, 3909, NULL),
(3910, 'legal department', '/ˈliːɡəl dɪˈpɑːrtmənt/', 'noun', '{"zh-TW":["法律部門"],"en":["the in-house team responsible for managing legal matters"]}', NULL, 'consult the legal department / legal department approval', '[{"en":"All major contracts are reviewed by the legal department.","zh-TW":"所有重大合約都由法律部門審查。"},{"en":"The legal department advises on regulatory compliance and disputes.","zh-TW":"法律部門就監管合規和糾紛提供建議。"}]', NULL, NULL, 5, 3910, NULL),
(3911, 'legal due diligence', '/ˈliːɡəl djuː ˈdɪlɪdʒəns/', 'noun', '{"zh-TW":["法律盡職調查"],"en":["a review of a company''s legal documents, contracts, and liabilities before a transaction"]}', NULL, 'conduct legal due diligence / legal due diligence findings', '[{"en":"Legal due diligence identified three pending lawsuits not previously disclosed.","zh-TW":"法律盡職調查識別了三起先前未披露的未決訴訟。"},{"en":"Legal due diligence is a critical step in any merger or acquisition process.","zh-TW":"法律盡職調查是任何合併或收購流程中的關鍵步驟。"}]', NULL, NULL, 5, 3911, NULL),
(3912, 'legal entity', '/ˈliːɡəl ˈentɪti/', 'noun', '{"zh-TW":["法律實體；法人"],"en":["an organization recognized by law as having rights and responsibilities"]}', NULL, 'registered legal entity / create a legal entity / separate legal entity', '[{"en":"Each subsidiary is a separate legal entity with its own liabilities.","zh-TW":"每家子公司是一個獨立的法律實體，擁有自己的責任。"},{"en":"A legal entity must be established before applying for a business license.","zh-TW":"申請營業執照前必須建立一個法律實體。"}]', NULL, NULL, 4, 3912, NULL),
(3913, 'legislation', '/ˌlɛdʒɪsˈleɪʃən/', 'noun', '{"zh-TW":["立法；法規"],"en":["laws considered as a group","a law or set of laws made by a government"]}', NULL, 'pass legislation / new legislation; introduce/pass legislation / environmental legislation', '[{"en":"New legislation was passed yesterday.","zh-TW":"新的法規昨天通過了。"},{"en":"The legislation aims to reduce pollution.","zh-TW":"該法規旨在減少污染。"},{"en":"New legislation was passed to protect consumers.","zh-TW":"通過了新的立法以保護消費者。"},{"en":"The legislation will take effect next month.","zh-TW":"該法規將於下個月生效。"}]', '{"verb":"legislate","noun2":"legislator","adjective":"legislative","noun":"legislation, legislator, legislature"}', NULL, 4, 3913, 589),
(3914, 'legislative', '/ˈledʒɪslətɪv/', 'adjective', '{"zh-TW":["立法的"],"en":["relating to the function of making laws"]}', NULL, 'legislative process / legislative reform / legislative body', '[{"en":"The legislative process requires approval from both chambers of parliament.","zh-TW":"立法程序需要議會兩院的批准。"},{"en":"The legislative agenda was packed with controversial bills.","zh-TW":"立法議程充滿了有爭議的法案。"}]', '{"noun":"legislature","adverb":"legislatively"}', NULL, 4, 3914, NULL),
(3915, 'legitimacy', '/lɪˈdʒɪtɪməsi/', 'noun', '{"zh-TW":["合法性；正當性"],"en":["the quality of conforming to law or rules; being generally accepted"]}', NULL, 'political legitimacy / organizational legitimacy / legitimacy crisis', '[{"en":"A government derives its legitimacy from the consent of the governed.","zh-TW":"政府的合法性來自被統治者的同意。"},{"en":"Corporate legitimacy depends on ethical behavior and stakeholder trust.","zh-TW":"企業合法性取決於道德行為和利益相關者的信任。"}]', '{"adjective":"legitimate","adverb":"legitimately"}', NULL, 4, 3915, NULL),
(3916, 'legitimate', '/lɪˈdʒɪtɪmət/', 'adjective', '{"zh-TW":["合法的；正當的"],"en":["conforming to the law; reasonable"]}', NULL, 'legitimate business/concern/reason', '[{"en":"This is a perfectly legitimate business.","zh-TW":"這是一家完全合法的企業。"},{"en":"Employees have legitimate concerns about job security.","zh-TW":"員工對工作保障有正當的擔憂。"}]', '{"noun":"legitimacy","adjective":"legitimate","verb":"legitimize","adverb":"legitimately"}', NULL, 4, 3916, NULL),
(3917, 'lend', '/lend/', 'verb', '{"zh-TW":["借出；貸款"],"en":["to give something to someone temporarily"]}', NULL, 'lend money / lend support/assistance', '[{"en":"The bank agreed to lend us the money.","zh-TW":"銀行同意借錢給我們。"},{"en":"Could you lend me your notes from the meeting?","zh-TW":"你能把會議記錄借我看看嗎？"}]', '{"noun":"lender, lending","verb":"lend"}', NULL, 1, 3917, NULL),
(3918, 'lender', '/ˈlendər/', 'noun', '{"zh-TW":["貸款方；放款人"],"en":["a bank or other organization that provides money to borrowers"]}', NULL, 'approach a lender / negotiate with the lender', '[{"en":"The company approached multiple lenders to secure the best rate.","zh-TW":"公司與多家貸款方接洽以獲得最佳利率。"},{"en":"The lender required collateral before approving the mortgage.","zh-TW":"貸款方在批准抵押貸款前要求提供抵押品。"}]', '{"verb":"lend","opposite":"borrower"}', NULL, 2, 3918, NULL),
(3919, 'lenient', '/ˈliːniənt/', 'adjective', '{"zh-TW":["寬大的；仁慈的"],"en":["not strict in punishing or enforcing rules"]}', NULL, 'lenient policy/approach/sentence', '[{"en":"The company has a lenient policy on remote work.","zh-TW":"公司對遠端工作有寬鬆的政策。"},{"en":"The judge was lenient with first-time offenders.","zh-TW":"法官對初犯者較為寬大。"}]', '{"noun":"leniency","adjective":"lenient","adverb":"leniently"}', NULL, 3, 3919, NULL),
(3920, 'lessee', '/leˈsiː/', 'noun', '{"zh-TW":["承租人；租客"],"en":["a person who holds a property under a lease"]}', NULL, 'lessee obligations / lessee rights / commercial lessee', '[{"en":"The lessee must maintain the property in good condition.","zh-TW":"承租人必須保持物業處於良好狀態。"},{"en":"As the lessee, she was responsible for all utility costs.","zh-TW":"作為承租人，她負責所有水電費。"}]', '{"opposite":"lessor"}', NULL, 2, 3920, NULL),
(3921, 'lesson', '/ˈlɛsən/', 'noun', '{"zh-TW":["課程；教訓"],"en":["a period of teaching","something learned from experience"]}', NULL, 'learn a lesson / lessons learned', '[{"en":"We documented lessons learned from the project.","zh-TW":"我們記錄了專案的經驗教訓。"},{"en":"That failure taught us a valuable lesson.","zh-TW":"那次失敗教了我們寶貴的一課。"}]', '{"noun":"lesson"}', NULL, 2, 3921, NULL),
