(3923, 'lessor', '/ˈlesɔːr/', 'noun', '{"zh-TW":["出租人；房東"],"en":["the person or organization that grants a lease on property"]}', NULL, 'responsibilities of the lessor / lessor obligations', '[{"en":"The lessor was responsible for structural repairs to the building.","zh-TW":"出租人負責建築的結構修繕。"},{"en":"As lessor, the company manages over 200 rental properties.","zh-TW":"作為出租人，該公司管理著200多個出租物業。"}]', '{"opposite":"lessee"}', NULL, 2, 3923, NULL),
(3924, 'let', 'lɛt', 'verb', '{"zh-TW":["讓；允許","出租"],"en":["to allow something to happen","to rent out"]}', NULL, 'let someone know/in', '[{"en":"Please let us know your decision.","zh-TW":"請讓我們知道您的決定。"}]', NULL, NULL, 1, 3924, NULL),
(3925, 'letter', '/ˈlɛtər/', 'noun', '{"zh-TW":["信件；字母"],"en":["a written message","a character of the alphabet"]}', NULL, 'cover letter / letter of recommendation', '[{"en":"Please attach a cover letter with your resume.","zh-TW":"請附上求職信和履歷。"},{"en":"He received a letter of recommendation.","zh-TW":"他收到了一封推薦信。"}]', '{"noun":"letter"}', NULL, 2, 3925, NULL),
(3926, 'letter of credit', '/ˈletər əv ˈkredɪt/', 'noun', '{"zh-TW":["信用狀"],"en":["a bank document guaranteeing payment to a seller if conditions are met"]}', NULL, 'issue a letter of credit / letter of credit terms / documentary letter of credit', '[{"en":"The exporter required a letter of credit before shipping goods.","zh-TW":"出口商在發貨前要求開立信用狀。"},{"en":"Letters of credit reduce payment risk in international trade.","zh-TW":"信用狀降低了國際貿易中的付款風險。"}]', '{"abbreviation":"LC / L/C"}', NULL, 5, 3926, NULL),
(3927, 'letter of guarantee', '/ˈletər əv ˌɡærənˈtiː/', 'noun', '{"zh-TW":["擔保函；保函"],"en":["a written commitment by a bank or institution guaranteeing fulfillment of an obligation"]}', NULL, 'issue a letter of guarantee / letter of guarantee terms', '[{"en":"The contractor provided a letter of guarantee for the advance payment received.","zh-TW":"承包商為收到的預付款提供了保函。"},{"en":"A letter of guarantee protects the beneficiary if the applicant defaults.","zh-TW":"如果申請人違約，保函保護受益人。"}]', NULL, NULL, 5, 3927, NULL),
