(3930, 'leverage', '/ˈlevərɪdʒ/', 'noun, verb', '{"zh-TW":["槓桿；影響力","利用；借助"],"en":["influence or advantage; borrowing for investment","to use to maximum advantage"]}', NULL, 'leverage resources/technology/data', '[{"en":"We should leverage our existing technology.","zh-TW":"我們應該充分利用現有技術。"},{"en":"The company has significant leverage in negotiations.","zh-TW":"公司在談判中有很大的影響力。"}]', '{"noun":"leverage","verb":"leverage"}', NULL, 3, 3930, 696),
(3931, 'leverage buyout', '/ˈlevərɪdʒ ˈbaɪaʊt/', 'noun', '{"zh-TW":["槓桿收購"],"en":["the acquisition of a company using a significant amount of borrowed money"]}', NULL, 'complete a leverage buyout / leverage buyout financing', '[{"en":"The private equity firm completed a leverage buyout using 70% debt financing.","zh-TW":"私募股權公司使用70%的債務融資完成了槓桿收購。"},{"en":"Leverage buyouts require strong cash flow to service the acquisition debt.","zh-TW":"槓桿收購需要強勁的現金流來償還收購債務。"}]', '{"abbreviation":"LBO"}', NULL, 5, 3931, NULL),
(3932, 'leverage ratio', '/ˈlevərɪdʒ ˈreɪʃioʊ/', 'noun', '{"zh-TW":["槓桿比率"],"en":["the ratio measuring the extent to which a company uses borrowed money to fund operations"]}', NULL, 'calculate the leverage ratio / high leverage ratio', '[{"en":"A high leverage ratio means the company is heavily dependent on debt financing.","zh-TW":"高槓桿比率意味著公司嚴重依賴債務融資。"},{"en":"Regulators monitor banks'' leverage ratios to ensure financial stability.","zh-TW":"監管機構監控銀行的槓桿比率以確保金融穩定。"}]', NULL, NULL, 5, 3932, NULL),
(3933, 'leverage technology', '/''levərɪdʒ tekˌnɒlədʒi/', 'phrase', '{"zh-TW":["利用技術；借助技術"],"en":["to use technology as a tool to achieve a goal more effectively or efficiently"]}', NULL, 'leverage technology to / leverage technology for / effectively leverage technology', '[{"en":"The nonprofit leverages technology to reach more people in need at lower cost.","zh-TW":"這家非營利組織利用技術以更低的成本接觸更多需要幫助的人。"},{"en":"Modern businesses must learn to leverage technology to remain competitive.","zh-TW":"現代企業必須學會利用技術才能保持競爭力。"}]', '{"verb":"leverage","noun":"technology"}', NULL, 5, 3933, NULL),
(3934, 'leveraged', '/ˈlevərɪdʒd/', 'adjective', '{"zh-TW":["槓桿化的；借貸融資的"],"en":["financed significantly through borrowed funds"]}', NULL, 'highly leveraged / leveraged position / leveraged acquisition', '[{"en":"The highly leveraged company struggled to service its debt.","zh-TW":"高度槓桿化的公司難以償還其債務。"},{"en":"A leveraged buyout uses the target company''s assets as collateral.","zh-TW":"槓桿收購使用目標公司的資產作為抵押品。"}]', '{"verb":"leverage","noun":"leverage"}', NULL, 3, 3934, NULL),
