(3936, 'levy', '/ˈlevi/', 'noun, verb', '{"zh-TW":["徵收；稅款"],"en":["a tax or fee imposed by a government"]}', NULL, 'levy a tax/fine / impose a levy', '[{"en":"The government levied a new tax on imports.","zh-TW":"政府對進口商品徵收了新稅。"},{"en":"A levy was imposed on carbon emissions.","zh-TW":"對碳排放徵收了稅款。"}]', '{"noun":"levy","verb":"levy"}', NULL, 1, 3936, NULL),
(3937, 'lexicon', '/ˈleksɪkɒn/', 'noun', '{"zh-TW":["詞彙；詞典"],"en":["the vocabulary of a person, language, or branch of knowledge"]}', NULL, 'technical lexicon / academic lexicon / expand one''s lexicon', '[{"en":"The field has developed a specialized lexicon over decades.","zh-TW":"該領域幾十年來發展出一套專業詞彙。"},{"en":"Understanding the lexicon of finance is essential for analysts.","zh-TW":"理解金融詞彙對分析師至關重要。"}]', '{"adjective":"lexical"}', NULL, 3, 3937, NULL),
(3938, 'liability', '/ˌlaɪəˈbɪləti/', 'noun', '{"zh-TW":["責任；負債；不利因素"],"en":["legal responsibility; debts; a disadvantage"]}', NULL, 'limited liability / financial liability', '[{"en":"The company has limited liability for damages.","zh-TW":"公司對損害承擔有限責任。"},{"en":"Total liabilities exceeded assets by $2 million.","zh-TW":"總負債超過資產200萬美元。"}]', '{"noun":"liability","adjective":"liable"}', NULL, 3, 3938, 384),
(3939, 'liability clause', '/ˌlaɪəˈbɪlɪti klɔːz/', 'noun', '{"zh-TW":["責任條款；免責條款"],"en":["a contract provision defining or limiting a party''s legal responsibility"]}', NULL, 'limit liability clause / liability clause in a contract', '[{"en":"The liability clause capped damages at 12 months of contract value.","zh-TW":"責任條款將損害賠償上限設定為合同價值的12個月。"},{"en":"Lawyers carefully reviewed the liability clause before signing.","zh-TW":"律師在簽署前仔細審查了責任條款。"}]', NULL, NULL, 5, 3939, NULL),
(3940, 'liability insurance', '/ˌlaɪəˈbɪlɪti ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["責任保險"],"en":["insurance that protects against claims of liability"]}', NULL, 'purchase liability insurance / liability insurance coverage', '[{"en":"Professional liability insurance protects consultants from claims.","zh-TW":"專業責任保險保護顧問免受索賠。"},{"en":"The company carries comprehensive liability insurance.","zh-TW":"公司持有全面的責任保險。"}]', NULL, NULL, 5, 3940, NULL),
(3941, 'liability management', '/laɪəˈbɪlɪti ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["負債管理"],"en":["strategies to manage and optimize a company financial obligations"]}', NULL, 'conduct liability management / liability management exercise', '[{"en":"The treasury team conducted a liability management exercise to reduce costs.","zh-TW":"財資團隊進行了負債管理操作以降低成本。"},{"en":"Liability management involves refinancing, repurchasing, and restructuring debt.","zh-TW":"負債管理涉及債務再融資、回購和重組。"}]', NULL, NULL, 5, 3941, NULL),
(3942, 'liable', '/ˈlaɪəbl/', 'adjective', '{"zh-TW":["有責任的；可能的"],"en":["legally responsible; likely to"]}', NULL, 'be liable for / liable to', '[{"en":"The company is liable for any damages caused.","zh-TW":"公司對造成的任何損害負有責任。"},{"en":"Prices are liable to change without notice.","zh-TW":"價格可能在沒有通知的情況下變更。"}]', '{"noun":"liability","adjective":"liable"}', NULL, 2, 3942, NULL),
